function calculateInstitutionalExecutionPlan(signal = {}, tradeAmount = 0) {
  const symbol = normalizeSymbol(signal.symbol);
  const price = Number(signal.current || signal.price || 0);
  const volume = Number(signal.volume || signal.barVolume || 0);
  const bid = Number(signal.bid || 0);
  const ask = Number(signal.ask || 0);
  const spreadPercent =
    bid > 0 && ask > 0 && price > 0
      ? ((ask - bid) / price) * 100
      : 0;
  const dollarVolume = Number(
    signal.dollarVolume ||
    (price > 0 && volume > 0 ? price * volume : 0)
  );
  const liquidityScore = clampScore(
    35 +
    (dollarVolume >= 500000 ? 20 : 0) +
    (dollarVolume >= 2000000 ? 20 : 0) +
    (volume >= 100000 ? 10 : 0) +
    (volume >= 500000 ? 10 : 0) -
    (spreadPercent > 0.75 ? 12 : 0) -
    (spreadPercent > 1.5 ? 20 : 0) -
    (spreadPercent > 3 ? 30 : 0)
  );
  const slippageRiskScore = clampScore(
    25 +
    (spreadPercent > 0.5 ? 15 : 0) +
    (spreadPercent > 1 ? 20 : 0) +
    (spreadPercent > 2 ? 25 : 0) +
    (dollarVolume < 500000 ? 20 : 0) -
    (dollarVolume >= 2000000 ? 15 : 0)
  );
  const executionConfidence = clampScore(
    liquidityScore * 0.65 +
    (100 - slippageRiskScore) * 0.35
  );
  const shouldUseIceberg =
    tradeAmount >= 500 &&
    liquidityScore < 75;
  const sliceCount =
    shouldUseIceberg
      ? liquidityScore >= 65
        ? 2
        : liquidityScore >= 50
          ? 3
          : 4
      : 1;
  const suggestedSliceAmount =
    sliceCount > 0
      ? Number((Number(tradeAmount || 0) / sliceCount).toFixed(2))
      : Number(tradeAmount || 0);
  const executionMode =
    executionConfidence >= 80
      ? "FAST_EXECUTION"
      : executionConfidence >= 65
        ? "STAGGERED_EXECUTION"
        : executionConfidence >= 50
          ? "ICEBERG_EXECUTION"
          : "AVOID_WEAK_EXECUTION";
  const executionRiskPenalty =
    (spreadPercent > 3 ? 0.35 : 0) +
    (spreadPercent > 1.5 ? 0.2 : 0) +
    (spreadPercent > 0.75 ? 0.1 : 0) +
    (dollarVolume < 250000 ? 0.25 : 0) +
    (dollarVolume < 500000 ? 0.15 : 0) +
    (slippageRiskScore >= 75 ? 0.2 : 0);
  const executionQualityBoost =
    executionConfidence >= 85 && spreadPercent <= 0.5
      ? 0.08
      : executionConfidence >= 75 && spreadPercent <= 0.75
        ? 0.04
        : 0;
  const rawExecutionMultiplier =
    executionConfidence >= 85
      ? 1.05
      : executionConfidence >= 75
        ? 0.95
        : executionConfidence >= 65
          ? 0.8
          : executionConfidence >= 50
            ? 0.55
            : 0.25;
  const executionSizeMultiplier = Number(
    Math.max(
      0.2,
      Math.min(
        1.1,
        rawExecutionMultiplier -
        executionRiskPenalty +
        executionQualityBoost
      )
    ).toFixed(2)
  );
  const shouldReduceSize =
    executionSizeMultiplier < 0.85 ||
    slippageRiskScore >= 70 ||
    executionConfidence < 65;
  return {
    symbol,
    phase: "30_INSTITUTIONAL_EXECUTION_LAYER",
    executionMode,
    liquidityScore,
    slippageRiskScore,
    executionConfidence,
    spreadPercent: Number(spreadPercent.toFixed(3)),
    dollarVolume: Number(dollarVolume.toFixed(2)),
    shouldUseIceberg,
    sliceCount,
    suggestedSliceAmount,
    shouldReduceSize,
    executionSizeMultiplier,
    executionRiskPenalty: Number(executionRiskPenalty.toFixed(2)),
    executionQualityBoost: Number(executionQualityBoost.toFixed(2)),
    rawExecutionMultiplier,
    stealthExecutionRouting:
      executionMode === "ICEBERG_EXECUTION" ||
      executionMode === "STAGGERED_EXECUTION",
    reason: "STATE_UPDATED",
  };
}
