function detectMarketRegime(stockSignals = []) {
  if (!CONFIG.enableMarketRegimeEngine) {
    return {
      state: "cautious bullish",
      label: "Cautious Bullish",
      exposureMultiplier: 0.75,
      riskMessage: "Market regime engine disabled. Using cautious default.",
    };
  }
  const signals = Array.isArray(stockSignals) ? stockSignals : [];
  if (!signals.length) {
    return {
      state: "defensive",
      label: "Defensive",
      exposureMultiplier: CONFIG.defensiveExposureMultiplier,
      riskMessage: "No strong market signal. Reducing exposure.",
    };
  }
  const avgScore =
    signals.reduce((sum, s) => sum + Number(s.institutionalScore || s.score || 0), 0) /
    signals.length;
  const positiveCount = signals.filter((s) => Number(s.percentChange || 0) > 0).length;
  const positiveRatio = positiveCount / signals.length;
  const fakeBreakoutCount = signals.filter(
    (s) => s.confirmations?.fakeBreakout === true
  ).length;
  const riskCount = signals.filter(
    (s) =>
      s.confirmations?.newsRisk === true ||
      Number(s.riskScore || 100) < 50
  ).length;
  const riskRatio = riskCount / signals.length;
  const fakeBreakoutRatio = fakeBreakoutCount / signals.length;
  if (riskRatio >= 0.35 || fakeBreakoutRatio >= 0.25) {
    return {
      state: "panic/high volatility",
      label: "Panic / High Volatility",
      exposureMultiplier: CONFIG.panicExposureMultiplier,
      riskMessage: "High risk detected. New auto-buys should be blocked or heavily reduced.",
    };
  }
  if (avgScore >= 80 && positiveRatio >= 0.65) {
    return {
      state: "aggressive bullish",
      label: "Aggressive Bullish",
      exposureMultiplier: CONFIG.aggressiveBullishExposureMultiplier,
      riskMessage: "Strong opportunity environment. Normal exposure allowed.",
    };
  }
  if (avgScore >= 65 && positiveRatio >= 0.5) {
    return {
      state: "cautious bullish",
      label: "Cautious Bullish",
      exposureMultiplier: CONFIG.cautiousBullishExposureMultiplier,
      riskMessage: "Good but not perfect conditions. Reduced exposure.",
    };
  }
  return {
    state: "defensive",
    label: "Defensive",
    exposureMultiplier: CONFIG.defensiveExposureMultiplier,
    riskMessage: "Weak or choppy conditions. Exposure reduced.",
  };
}
function calculateMarketPhase(stockSignals = [], cryptoSignals = []) {
  const allSignals = [...stockSignals, ...cryptoSignals];
  const avgScore =
    allSignals.reduce((sum, s) => sum + Number(s.score || 0), 0) /
    Math.max(1, allSignals.length);
  const eliteCount = allSignals.filter((s) => Number(s.score || 0) >= 82).length;
  const weakCount = allSignals.filter((s) => Number(s.score || 0) < 65).length;
  const fakeBreakoutCount = allSignals.filter(
    (s) => s.confirmations?.fakeBreakout === true
  ).length;
  const advancingCount = stockSignals.filter(
    (s) => Number(s.percentChange || 0) > 0
  ).length;
  const breadthRatio =
    advancingCount / Math.max(1, stockSignals.length);
  const eliteRatio =
    eliteCount / Math.max(1, allSignals.length);
  const weakRatio =
    weakCount / Math.max(1, allSignals.length);
  const fakeBreakoutRatio =
    fakeBreakoutCount / Math.max(1, allSignals.length);
  const marketStress = Number(engineState.marketStressLevel || 0);
  const marketVolatility = Number(engineState.marketVolatility || 0);
  const marketMomentum = Number(engineState.marketMomentumScore || 0);
  const phaseScore = clampScore(
    avgScore * 0.28 +
    eliteRatio * 100 * 0.22 +
    breadthRatio * 100 * 0.18 +
    Math.max(0, marketMomentum) * 1.2 -
    weakRatio * 100 * 0.14 -
    fakeBreakoutRatio * 100 * 0.16 -
    marketStress * 0.45 -
    marketVolatility * 0.35
  );
  const phase =
    phaseScore >= 82 && eliteRatio >= 0.18 && fakeBreakoutRatio <= 0.12
      ? "ELITE_RISK_ON"
      : phaseScore >= 70 && breadthRatio >= 0.5
        ? "SELECTIVE_RISK_ON"
        : phaseScore >= 55
          ? "PROBE_ONLY"
          : marketStress >= 60 || fakeBreakoutRatio >= 0.25
            ? "DEFENSIVE_TRAP_MARKET"
            : "CASH_DEFENSIVE";
  const capitalMode =
    phase === "ELITE_RISK_ON"
      ? "ATTACK_ELITE_SETUPS"
      : phase === "SELECTIVE_RISK_ON"
        ? "NORMAL_SELECTIVE_BUYING"
        : phase === "PROBE_ONLY"
          ? "SMALL_PROBES_ONLY"
          : "PROTECT_CAPITAL";
  const buyAggressionMultiplier =
    phase === "ELITE_RISK_ON"
      ? 1.18
      : phase === "SELECTIVE_RISK_ON"
        ? 1
        : phase === "PROBE_ONLY"
          ? 0.72
          : 0.45;
  return {
    phase: "30_INSTITUTIONAL_MARKET_PHASE_ENGINE",
    updatedAt: new Date().toISOString(),
    marketPhase: phase,
    phaseScore,
    capitalMode,
    buyAggressionMultiplier,
    avgScore: Number(avgScore.toFixed(2)),
    eliteRatio: Number(eliteRatio.toFixed(2)),
    weakRatio: Number(weakRatio.toFixed(2)),
    breadthRatio: Number(breadthRatio.toFixed(2)),
    fakeBreakoutRatio: Number(fakeBreakoutRatio.toFixed(2)),
    marketStress,
    marketVolatility,
    marketMomentum,
    reason:
      `FakeBreakouts ${(fakeBreakoutRatio * 100).toFixed(1)}%`,
  };
}
