    symbol,
    phase: "17.6_SMART_EXIT_INTELLIGENCE",
    exitQualityScore,
    exitMode,
    shouldPartialProfit,
    shouldForceExit,
    shouldExtendHold,
    continuationFailure,
    runnerFailure,
    reason: "STATE_UPDATED",
