    gapRiskScore,
    shouldHoldOvernight,
    shouldTrimBeforeClose,
    shouldExitBeforeClose,
    score,
    technicalScore,
    continuationProbability,
    breakoutProbability,
    volumeConfirmationQuality,
    exhaustionRiskScore,
