function hydrateCryptoExecutionCandidate(candidate = {}) {
  const symbol = normalizeSymbol(candidate.symbol);
  if (!isCrypto(symbol)) return candidate;

  const finalizedSources = [
    ...(engineState.lastCryptoSignals || []),
    ...(engineState.topCryptoSignals || []),
    ...(engineState.lastSignals || []),
    ...(engineState.topSignals || []),
  ];
  const finalized = finalizedSources.find(
    (signal) => normalizeSymbol(signal?.symbol) === symbol
  ) || {};
  const compactSymbol = symbol.replaceAll("/", "");
  const slashSymbol = symbol.includes("/")
    ? symbol
    : symbol.endsWith("USD")
      ? `${symbol.slice(0, -3)}/USD`
      : symbol;
  const quote =
    engineState.liveQuoteCache?.[symbol] ||
    engineState.liveQuoteCache?.[compactSymbol] ||
    engineState.liveQuoteCache?.[slashSymbol] ||
    engineState.liveMarketMemory?.[symbol] ||
    engineState.liveMarketMemory?.[compactSymbol] ||
    engineState.liveMarketMemory?.[slashSymbol] ||
    {};
  const firstPositive = (...values) => {
    for (const value of values) {
      const parsed = Number(value);
      if (Number.isFinite(parsed) && parsed > 0) return parsed;
    }
    return 0;
  };
  const bid = firstPositive(quote.bid, quote.bp, quote.bidPrice);
  const ask = firstPositive(quote.ask, quote.ap, quote.askPrice);
  const spreadAvailable = bid > 0 && ask >= bid;
  const current = firstPositive(
    quote.price,
    quote.current,
    quote.livePrice,
    quote.last,
    finalized.current,
    finalized.price,
    candidate.current,
    candidate.price
  );
  const spreadPercent = spreadAvailable
    ? ((ask - bid) / ((ask + bid) / 2)) * 100
    : null;

  return {
    ...candidate,
    ...finalized,
    symbol,
    assetClass: "crypto",
    asset_class: "crypto",
    current,
    price: current,
    bid: spreadAvailable ? bid : null,
    ask: spreadAvailable ? ask : null,
    spreadAvailable,
    spreadPercent,
    spreadSource: spreadAvailable
      ? String(quote.liveQuoteSource || quote.source || "live_quote_cache")
      : "unavailable",
  };
}

async function rotateWeakCryptoIfBetter(signals, positions) {
  if (!["live_crypto", "smart"].includes(TRADING_MODE)) return false;
  if (CONFIG.realCashTradingUnlocked !== true) {
    recordOrder("CRYPTO_ROTATION_SKIPPED_CASH_LOCKED", "CRYPTO", {
      reason: "A rotation cannot sell unless its replacement buy is permitted.",
    });
    return false;
  }
  const cryptoPositions = positions.filter((p) => {
    const symbol = normalizeSymbol(p.symbol);
    return (
      symbol.includes("/") ||
      symbol.endsWith("USD") ||
      String(p.asset_class || "").toLowerCase() === "crypto"
    );
  });
  if (cryptoPositions.length < CONFIG.maxCryptoOpenTrades) return false;
  const openSymbols = new Set(
    cryptoPositions.map((p) => normalizeSymbol(p.symbol))
  );
  const topCandidateEvaluation = signals
    .map(hydrateCryptoExecutionCandidate)
    .map((signal) => ({
      signal,
      gate: evaluateCryptoTradeCandidate(signal, { minimumScore: 85 }),
    }))
    .filter(({ signal, gate }) => (
      gate.approved && !openSymbols.has(normalizeSymbol(signal.symbol))
    ))
    .sort((a, b) => b.gate.score - a.gate.score)[0];
  if (!topCandidateEvaluation) return false;
  const topCandidate = topCandidateEvaluation.signal;
  const topCandidateGate = topCandidateEvaluation.gate;
  const aiEntryScores = await getBotEntryScores();
  const weakest = cryptoPositions.reduce((weak, pos) => {
    const weakSymbol = normalizeSymbol(weak.symbol);
    const posSymbol = normalizeSymbol(pos.symbol);
    const weakScore = Number(
      aiEntryScores[weakSymbol] ||
      engineState.aiEntryScores?.[weakSymbol]?.score ||
      engineState.aiEntryScores?.[weakSymbol] ||
      0
    );
    const posScore = Number(
      aiEntryScores[posSymbol] ||
      engineState.aiEntryScores?.[posSymbol]?.score ||
      engineState.aiEntryScores?.[posSymbol] ||
      0
    );
    return posScore < weakScore ? pos : weak;
  });
  const clock = await getClock();
  const marketOpen = clock?.is_open === true;
  if (!marketOpen && TRADING_MODE !== "live_crypto") {
    recordOrder(
      "ROTATION_SKIPPED_MARKET_CLOSED",
      weakest?.symbol || "UNKNOWN",
      {
        replacementCandidate: topCandidate?.symbol,
      }
    );
    return false;
  }
  const weakestProfitPercent =
    Number(weakest.unrealized_plpc || 0) * 100;
  const weakestSymbol = normalizeSymbol(weakest.symbol);
  const weakestScore = Number(
    aiEntryScores[weakestSymbol] ||
    engineState.aiEntryScores?.[weakestSymbol]?.score ||
    engineState.aiEntryScores?.[weakestSymbol] ||
    0
  );
  const replacementScore = topCandidateGate.score;
  const scoreGap = replacementScore - weakestScore;
  if (scoreGap < CONFIG.replaceWeakestMinScoreGap) {
    recordOrder("CRYPTO_ROTATION_SKIPPED_SCORE_GAP", weakestSymbol, {
      replacementSymbol: topCandidate.symbol,
      replacementScore,
      weakestScore,
      scoreGap,
      requiredGap: CONFIG.replaceWeakestMinScoreGap,
      weakestProfitPercent,
    });
    return false;
  }
  const swingRotationCheck =
    canRunSwingSafeRotation(weakest, {
      scoreGap,
      weakestScore,
      replacementScore,
    });
  if (!swingRotationCheck.allowed) {
    recordOrder(
      "CRYPTO_ROTATION_SKIPPED_SWING_SAFE",
      weakest.symbol,
      {
        replacementSymbol: topCandidate.symbol,
        replacementScore: topCandidate.score,
        reason: swingRotationCheck.reason,
        weakestProfitPercent,
      }
    );
    return false;
  }
  const replacementBuyPreflight = validateLiveOrder(
    topCandidate.symbol,
    "BUY"
  );
  if (!replacementBuyPreflight.approved) {
    recordOrder(
      "CRYPTO_ROTATION_SKIPPED_BUY_PREFLIGHT",
      weakest.symbol,
      {
        replacementSymbol: topCandidate.symbol,
        blockReasons: replacementBuyPreflight.blockReasons,
      }
    );
    return false;
  }
  const weakestQty = Number(weakest.qty);
  if (!weakestQty || weakestQty <= 0) return false;
  try {
    const sellOrder = await placeCryptoMarketSell(
      weakestSymbol,
      weakestQty,
      `CRYPTO_ROTATE_TO_${normalizeSymbol(topCandidate.symbol)}`
    );
    recordOrder("CRYPTO_ROTATED_OUT", weakestSymbol, {
      replacementSymbol: topCandidate.symbol,
      replacementScore: topCandidate.score,
      weakestProfitPercent: Number(weakest.unrealized_plpc || 0) * 100,
      sellOrder,
    });
    markSwingSafeRotationUsed(weakestSymbol, topCandidate.symbol);
    delete engineState.highWaterMarks[weakestSymbol];
    const maxReplacementAttempts = 3;
    const scheduleReplacementAttempt = (attempt) => {
      setTimeout(() => {
        void attemptReplacementBuy(attempt);
      }, 2500);
    };
    const attemptReplacementBuy = async (attempt) => {
      try {
        const freshPositions = await getPositions();
        const weakestStillOpen = freshPositions.some((position) => (
          normalizeSymbol(position.symbol) === weakestSymbol &&
          Number(position.qty || 0) > 0
        ));
        if (weakestStillOpen) {
          const willRetry = attempt < maxReplacementAttempts;
          recordOrder(
            willRetry
              ? "CRYPTO_ROTATION_BUY_DEFERRED"
              : "CRYPTO_ROTATION_BUY_SKIPPED",
            topCandidate.symbol,
            {
              attempt,
              maxReplacementAttempts,
              reason: willRetry
                ? "Outgoing crypto sell is not filled; replacement will retry."
                : "Outgoing crypto sell did not fill before the bounded retry limit.",
            }
          );
          if (willRetry) scheduleReplacementAttempt(attempt + 1);
          return;
        }
        const replacementAlreadyOpen = freshPositions.some((position) => (
          normalizeSymbol(position.symbol) === normalizeSymbol(topCandidate.symbol) &&
          Number(position.qty || 0) > 0
        ));
        if (replacementAlreadyOpen) {
          recordOrder("CRYPTO_ROTATION_BUY_ALREADY_FILLED", topCandidate.symbol, {
            attempt,
            replacedSymbol: weakestSymbol,
          });
          return;
        }
        const refreshedCandidate = hydrateCryptoExecutionCandidate(topCandidate);
        const refreshedCandidateGate = evaluateCryptoTradeCandidate(
          refreshedCandidate,
          { minimumScore: 85 }
        );
        const refreshedLivePreflight = validateLiveOrder(
          refreshedCandidate.symbol,
          "BUY"
        );
        if (!refreshedCandidateGate.approved || !refreshedLivePreflight.approved) {
          const willRetry = attempt < maxReplacementAttempts;
          const reasons = [
            ...refreshedCandidateGate.reasons,
            ...(refreshedLivePreflight.blockReasons || []),
          ];
          recordOrder(
            willRetry
              ? "CRYPTO_ROTATION_BUY_DEFERRED"
              : "CRYPTO_ROTATION_BUY_SKIPPED",
            topCandidate.symbol,
            {
              attempt,
              maxReplacementAttempts,
              reason: `Refreshed replacement evidence failed: ${reasons.join(", ")}`,
              refreshedCandidateGate,
              refreshedLivePreflight,
            }
          );
          if (willRetry) scheduleReplacementAttempt(attempt + 1);
          return;
        }
        const [account, freshAiOwnedSymbols] = await Promise.all([
          getAccount(),
          getBotOwnedSymbols(),
        ]);
        const freshAiPositions = freshPositions.filter((position) => {
          const positionSymbol = normalizeSymbol(position.symbol);
          return (
            freshAiOwnedSymbols.has(positionSymbol) ||
            engineState.aiManagedSymbols?.includes(positionSymbol)
          );
        });
        const adaptiveCryptoSizing =
          calculateAdaptiveCryptoPositionSize(refreshedCandidate, account);
        const cryptoMaxBudget =
          Number(account?.equity || 0) *
          (Number(CONFIG.maxBotExposurePercent || 0) / 100) *
          (Number(CONFIG.cryptoMaxExposureShareOfBotExposure || 30) / 100);
        const currentCryptoExposure = freshAiPositions.reduce((sum, position) => {
          const positionSymbol = normalizeSymbol(position.symbol);
          return isCrypto(positionSymbol)
            ? sum + Math.abs(Number(position.market_value || 0))
            : sum;
        }, 0);
        const remainingCryptoBudget = Math.max(
          0,
          cryptoMaxBudget - currentCryptoExposure
        );
        const totalBotExposure = getBotExposure(freshAiPositions);
        const totalMaxBotBudget =
          Number(account?.equity || 0) *
          (Number(CONFIG.maxBotExposurePercent || 80) / 100);
        const remainingTotalBotBudget = Math.max(
          0,
          totalMaxBotBudget - totalBotExposure
        );
        const tradeAmount = Number(
          Math.min(
            adaptiveCryptoSizing.recommendedAmount,
            remainingCryptoBudget,
            remainingTotalBotBudget,
            getCryptoAvailableBuyingPower(account)
          ).toFixed(2)
        );
        if (tradeAmount < 5) {
          recordFailedOrder(
            "CRYPTO_ROTATION_BUY_SKIPPED",
            topCandidate.symbol,
            "Not enough cash after rotation"
          );
          return;
        }
        const buyOrder = await placeCryptoMarketBuy(
          refreshedCandidate.symbol,
          tradeAmount
        );
        markAiManagedSymbol(refreshedCandidate.symbol);
        engineState.aiEntryScores[normalizeSymbol(refreshedCandidate.symbol)] = {
          score: refreshedCandidateGate.score,
          entryType: "CRYPTO_ROTATED_IN",
          replacedSymbol: weakestSymbol,
          tradeAmount,
          enteredAt: new Date().toISOString(),
        };
        recordOrder("CRYPTO_ROTATED_IN", refreshedCandidate.symbol, {
          score: refreshedCandidateGate.score,
          tradeAmount,
          replacedSymbol: weakestSymbol,
          attempt,
          buyOrder,
        });
        journalTradeEntry(refreshedCandidate.symbol, {
          entryType: "CRYPTO_ROTATED_IN",
          assetClass: "crypto",
          entryPrice:
            refreshedCandidate.current || refreshedCandidate.price || 0,
          score: refreshedCandidateGate.score,
          strategy: "crypto_rotation",
          sector: "Crypto",
          marketRegime:
            engineState.marketRegime?.state || "unknown",
          confirmations: refreshedCandidate.confirmations || {},
          tradeAmount,
        });
      } catch (err) {
        if (attempt < maxReplacementAttempts) {
          recordOrder("CRYPTO_ROTATION_BUY_DEFERRED", topCandidate.symbol, {
            attempt,
            maxReplacementAttempts,
            reason: err.message,
          });
          scheduleReplacementAttempt(attempt + 1);
        } else {
          recordFailedOrder("CRYPTO_ROTATION_BUY_FAILED", topCandidate.symbol, err.message);
        }
      }
    };
    scheduleReplacementAttempt(1);
    return true;
  } catch (err) {
    recordFailedOrder("CRYPTO_ROTATION_SELL_FAILED", weakestSymbol, err.message);
    return false;
  }
}
function getCryptoAvailableBuyingPower(account = {}) {
  const cash = Number(account?.cash || 0);
  const cryptoBuyingPower = Number(account?.crypto_buying_power || 0);
  const nonMarginableBuyingPower = Number(account?.non_marginable_buying_power || 0);
  return Math.max(
    0,
    cryptoBuyingPower,
    nonMarginableBuyingPower,
    cash
  );
}
function calculateAdaptiveCryptoPositionSize(signal = {}, account = {}) {
  const equity = Number(account?.equity || 0);
  const availableCryptoBuyingPower = getCryptoAvailableBuyingPower(account);
  const score = Number(signal.score || 0);
  const technicalScore = Number(
    signal.technicalScore ||
    signal.technical?.score ||
    signal.technicalIntelligence?.institutionalEntryScore ||
    0
  );
  const statisticalScore = Number(
    signal.statisticalScore ||
    signal.statisticalEdge?.statisticalEdgeScore ||
    0
  );
  const percentChange = Math.abs(Number(signal.percentChange || 0));
  const baseCryptoBudget =
    equity *
    (CONFIG.maxBotExposurePercent / 100) *
    (CONFIG.cryptoMaxExposureShareOfBotExposure / 100);
  const qualityMultiplier =
    score >= 90 ? 1 :
      score >= 80 ? 0.75 :
        score >= 70 ? 0.5 : 0.25;
  const technicalMultiplier =
    technicalScore >= 80 || statisticalScore >= 75
      ? 1
      : technicalScore >= 65
        ? 0.75
        : 0.5;
  const volatilityMultiplier =
    percentChange >= 20 ? 0.85 :
      percentChange >= 12 ? 1.15 :
        percentChange >= 8 ? 1 :
          percentChange >= 5 ? 0.9 : 1;
  const macroMultiplier =
    engineState.macroRiskState?.shouldBlockNewTrades
      ? 0
      : Number(engineState.macroRiskState?.macroExposureMultiplier || 1);
  const rawRecommendedAmount =
    baseCryptoBudget *
    qualityMultiplier *
    technicalMultiplier *
    volatilityMultiplier *
    macroMultiplier;
  const minCryptoTradeAmount = Number(
    CONFIG.minCryptoTradeAmount || CONFIG.minAutonomousTradeAmount || 25
  );
  const cappedRecommendedAmount = Math.min(
    rawRecommendedAmount,
    availableCryptoBuyingPower
  );
  const recommendedAmount =
    cappedRecommendedAmount > 0 && cappedRecommendedAmount < minCryptoTradeAmount
      ? minCryptoTradeAmount
      : cappedRecommendedAmount;
  return {
    recommendedAmount: Number(recommendedAmount.toFixed(2)),
    baseCryptoBudget: Number(baseCryptoBudget.toFixed(2)),
    availableCryptoBuyingPower: Number(availableCryptoBuyingPower.toFixed(2)),
    qualityMultiplier,
    technicalMultiplier,
    volatilityMultiplier,
    macroMultiplier,
    reason:
      `Crypto size adjusted by quality x${qualityMultiplier}, ` +
      `technical x${technicalMultiplier}, volatility x${volatilityMultiplier}, ` +
      `macro x${macroMultiplier}`,
  };
}
