function isLiveQuoteFresh(symbol, maxAgeSeconds = 90) {
  const cleanSymbol = normalizeSymbol(symbol);
  const quote = engineState.liveQuoteCache?.[cleanSymbol];
  if (!quote?.updatedAt) {
    return {
      fresh: false,
      ageSeconds: null,
      reason: "No live quote available.",
    };
  }
  const ageSeconds = Math.max(
    0,
    Math.round((Date.now() - new Date(quote.updatedAt).getTime()) / 1000)
  );
  return {
    fresh: ageSeconds <= maxAgeSeconds,
    ageSeconds,
    quote,
    reason:
      ageSeconds <= maxAgeSeconds
        ? "Live quote fresh."
        : `Live quote stale: ${ageSeconds}s old.`,
  };
}
let lastLiveSignalPushAt = 0;
let pendingLiveSignalPushPayload = null;
let liveSignalPushTimer = null;
function pushLiveSignalUpdate(payload = {}) {
  pendingLiveSignalPushPayload = payload;
  const now = Date.now();
  const elapsedMs = now - Number(lastLiveSignalPushAt || 0);
  const minPushIntervalMs = 750;
  if (elapsedMs < minPushIntervalMs) {
    if (!liveSignalPushTimer) {
      liveSignalPushTimer = setTimeout(() => {
        liveSignalPushTimer = null;
        pushLiveSignalUpdate(pendingLiveSignalPushPayload || {});
      }, minPushIntervalMs - elapsedMs);
    }
    return;
  }
  lastLiveSignalPushAt = now;
  const finalPayload =
    pendingLiveSignalPushPayload || payload;
  const message = `data: ${JSON.stringify({
    ...finalPayload,
    pushedAt: new Date().toISOString(),
  })}\n\n`;
  pendingLiveSignalPushPayload = null;
  pushBackendStreamEvent("SIGNAL_EVENT", {
    ...finalPayload,
  });
  for (const client of liveSignalClients) {
    try {
      client.write(message);
    } catch {
      liveSignalClients.delete(client);
    }
  }
}
function pushBackendStreamEvent(type, payload = {}) {
  const event = {
    id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    type,
    generatedAt: new Date().toISOString(),
    payload,
  };
  backendStreamReplayBuffer.unshift(event);
  backendStreamReplayBuffer.splice(100);
  const message = `id: ${event.id}\nevent: ${type}\ndata: ${JSON.stringify(event)}\n\n`;
  for (const client of backendStreamClients) {
    try {
      const allowedSymbols = client.allowedSymbols || [];
      const eventSymbol =
        normalizeSymbol(payload.symbol || payload?.quote?.symbol || "");
      if (
        allowedSymbols.length > 0 &&
        eventSymbol &&
        !allowedSymbols.includes(eventSymbol)
      ) {
        continue;
      }
      client.write(message);
    } catch {
      backendStreamClients.delete(client);
    }
  }
  return event;
}
function replayBackendStreamEvents(res, since = "") {
  const replayEvents = backendStreamReplayBuffer
    .slice()
    .reverse()
    .filter((event) => {
      if (!since) return true;
      return new Date(event.generatedAt).getTime() >
        new Date(since).getTime();
    })
    .slice(-25);
  for (const event of replayEvents) {
    res.write(
      `id: ${event.id}\nevent: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`
    );
  }
}
