function buildLiveOrderDedupKey(symbol, side, action = "LIVE_ORDER") {
  return `${normalizeSymbol(symbol)}_${String(side || "").toUpperCase()}_${String(action || "").toUpperCase()}`;
}
function checkAndMarkLiveDuplicateOrder(symbol, side, action = "LIVE_ORDER") {
  const key = buildLiveOrderDedupKey(symbol, side, action);
  const now = Date.now();
  const lastAt = Number(liveOrderDedupMap[key] || 0);
  if (lastAt && now - lastAt < LIVE_DUPLICATE_ORDER_WINDOW_MS) {
    return {
      duplicate: true,
      key,
      lastAt,
      ageMs: now - lastAt,
      windowMs: LIVE_DUPLICATE_ORDER_WINDOW_MS,
    };
  }
  return {
    duplicate: false,
    key,
    checkedAt: now,
    windowMs: LIVE_DUPLICATE_ORDER_WINDOW_MS,
  };
}
function markLiveOrderDedupSuccess(symbol, side, action = "LIVE_ORDER") {
  const key = buildLiveOrderDedupKey(symbol, side, action);
  const now = Date.now();
  liveOrderDedupMap[key] = now;
  return {
    key,
    markedAt: now,
    windowMs: LIVE_DUPLICATE_ORDER_WINDOW_MS,
  };
}
function cleanupLiveOrderDedupMap() {
  const cutoff = Date.now() - LIVE_DUPLICATE_ORDER_WINDOW_MS * 3;
  for (const [key, timestamp] of Object.entries(liveOrderDedupMap)) {
    if (Number(timestamp || 0) < cutoff) {
      delete liveOrderDedupMap[key];
    }
  }
}

function validateLiveOrder(symbol, side = "BUY") {
  const cleanSymbol = normalizeSymbol(symbol);
  const cryptoAsset = isCrypto(cleanSymbol);
  const cleanSide = String(side || "BUY").toUpperCase();

  const quote =
    engineState.liveQuoteCache?.[cleanSymbol] ||
    engineState.liveMarketMemory?.[cleanSymbol] ||
    {};

  const price = Number(quote.price || quote.current || 0);
  const spreadPercent = Number(quote.spreadPercent || 0);
  const quoteAgeSeconds = getLiveQuoteAgeSeconds(cleanSymbol);
  const quoteSource = quote.liveQuoteSource || quote.source || "";
  const quoteIsLive =
    quote.priceIsLive === true &&
    isLiveQuoteSource(quoteSource);

  const requireLiveProvider = LIVE_ORDER_REQUIRE_POLYGON_CONNECTED;
  const liveProviderEvidence = getLiveProviderEvidence(
    quoteSource,
    cryptoAsset
  );
  const decision = evaluatePreTradeRisk({
    order: { symbol: cleanSymbol, side: cleanSide, qty: 1 },
    options: { automated: false },
    context: {
      emergencyStopActive: false,
      realCashTradingUnlocked: true,
      autoTradingEnabled: true,
      dailyLossLocked: false,
      profitLocked: false,
      isCrypto: cryptoAsset,
      marketOpen: true,
      price,
      spreadPercent,
      quoteAgeSeconds,
      quoteIsLive,
      requireLiveProvider,
      liveProviderConnected: liveProviderEvidence.connected,
      liveProvider: liveProviderEvidence.provider,
      liveProviderReason: liveProviderEvidence.reason,
      maxQuoteAgeSeconds: LIVE_ORDER_MAX_QUOTE_AGE_SECONDS,
      maxSpreadPercent: LIVE_ORDER_MAX_SPREAD_PERCENT,
      maxExposurePercent: 100,
      maxOpenTrades: 0,
      account: { equity: Math.max(1, price) },
      positions: [],
    },
  });

  return {
    approved: decision.approved,
    symbol: cleanSymbol,
    side: cleanSide,
    price,
    spreadPercent,
    quoteAgeSeconds,
    quoteSource,
    quoteIsLive,
    liveProvider: liveProviderEvidence.provider,
    liveProviderConnected: liveProviderEvidence.connected,
    liveProviderReason: liveProviderEvidence.reason,
    polygonConnected: cryptoAsset
      ? isPolygonCryptoLiveConnected()
      : isPolygonLiveConnected(),
    blockReasons: decision.reasons,
    checkedAt: decision.checkedAt,
  };
}

